  9	export interface DisplayPosition { x: number; y: number }
 10	export interface DisplayBounds { width: number; height: number }
 11	export interface DisplayGeometry {
 12	  /** Unscaled CSS pixels, relative to the canvas origin or viewport top-left. */
 13	  position: DisplayPosition;
 14	  bounds: DisplayBounds;
 15	  coordinateSpace: 'canvas' | 'viewport';
 16	}
 17	export interface DisplayNodeBase extends DisplayGeometry {
 18	  id: string;
 19	  childIds: string[];
 20	  expansion: Expansion;
 21	  geometryPolicy: { placement: 'automatic' | 'manual'; sizing: 'content' | 'fixed' };
 22	  /** Restores the expanded allocation after rendering a collapsed header/bubble. */
 23	  expandedGeometry?: DisplayGeometry;
 24	}
 25	export function displayGeometry(position: DisplayPosition = { x: 0, y: 0 },
 26	  bounds: DisplayBounds = { width: 500, height: 200 }): Pick<DisplayNodeBase, keyof DisplayGeometry | 'geometryPolicy'> {
 27	  return { position, bounds, coordinateSpace: 'canvas', geometryPolicy: { placement: 'automatic', sizing: 'content' } };
 28	}
 29	export interface SelectionRegion extends DisplayNodeBase {
 30	  kind: 'selection';
 31	  /** Captured panel context; membership is owned exclusively by SelectionState. */
 32	  sourceBoxId: string;
 33	  sourceContentId: string;
 34	  sourceAscii: string;
 35	  sourceRevisionId?: string;
 36	  rect: MappingPocGridRect;
 37	  contentNodeIds?: readonly string[];
 38	  selectedIds: string[];
 39	  displayMode: ChildDisplayMode;
 40	  activeChildId?: string;
 41	}
 42	/** Legacy saved compaction presentation, independent of projection traversal. */
 43	export interface ProjectedFile {
